+export function evidenceReviewFixture(prompt: string, text: string): string {
+  if (!/```pace-review\n\{"version":2,/.test(prompt)) return text;
+  const criteria = [...prompt.matchAll(/^\- \[필수 기준 ([A-Z0-9-]+)\]/gm)].map((match) =>
