+    if (!/"version"\s*:\s*1\b/.test(json)) return block;
+    const updated = json.replace(/"version"\s*:\s*1\b/, `"version":2,"criteria":${JSON.stringify(criteria)}`)
+      .replace(/"severity"\s*:/g, '"impact":"goal","severity":');
+    return start + updated + end;
+  });
 }
